/** GRIDIRON LAB / Pressbox Night Shift
 * A simple game surface on top of strictly separated observed evidence and
 * reproducible synthetic football. Everything mounted here is same-origin.
 */
import {TEAMS,TEAM_MAP,DEFAULT_CONFIG,ENGINE_VERSION,simulateGame,simulateBatch,hash32} from './engine.js';
import {FORMATS,FORMAT_MAP,createTournament,simulateTournament,monteCarloTournament,ranked2026Field,swapTournamentSeeds} from './tournament.js';
import {observed,loadPublicData,sourceStatus,rosterForTeam,rosterSourceForTeam} from './observed.js';
import {evaluatedMatchup,loadResearchSnapshot,researchStatus} from './research.js';
import {getPlayerEvidence,loadPlayerEvidence,observedPropRows} from './playerEvidence.js';
import {modelComparison,loadModelComparison} from './modelCompare.js';
import {scoreEvidence,loadScoreEvidence} from './scoreEvidence.js';
import {playerModelEvaluation,loadPlayerModelEvaluation} from './playerModel.js';
import {histogram,atlas,scoreboardCurve,driveStrip,propBars} from './charts.js';
import {QUALIFICATION_RULES} from './cfpSelection.js';

const root=document.querySelector('#app');
const state={tournamentRuns:0,tab:'game',config:{...DEFAULT_CONFIG},game:null,forecast:null,runNumber:1,running:false,progress:0,
  worker:null,task:0,error:'',loading:true,datasets:[],selectedProp:null,format:'fbs12',
  tournament:createTournament('fbs12'),tournamentMC:null,selectedMatch:null,playoffBusy:false,mcBusy:false,
  sourcesReady:false,bracketViewRound:0,bracketViewPage:0,bracketQuadrant:'all',seedFrom:0,seedTo:1};
const fbs=TEAMS.filter(t=>t.division==='fbs');
const esc=x=>String(x??'').replace(/[&<>"']/g,y=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[y]));
const name=id=>TEAM_MAP[id]?.name||'Unknown team';
const short=id=>TEAM_MAP[id]?.short||'—';
const fmt=(x,d=1)=>Number.isFinite(+x)?Number(x).toFixed(d):'—';
const integer=x=>Number.isFinite(+x)?Math.round(x).toLocaleString('en-US'):'—';
const percent=x=>Number.isFinite(+x)?(100*x).toFixed(1)+'%':'—';
const ctl=(id,entries,current)=>`<select id="${esc(id)}" data-field="${esc(id)}">${entries.map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
const button=(id,label,cls='')=>`<button type="button" class="action ${cls}" data-action="${esc(id)}">${label}</button>`;
const tag=(label,type='simulation')=>`<span class="evidence-label ${type}">${esc(label)}</span>`;
const tabNames={game:'Game',playoff:'Playoffs',research:'Model & validation'};
const locationName=c=>c.venue==='a'?`${name(c.a)} home`:c.venue==='b'?`${name(c.b)} home`:'Neutral site';
const subtitle=(n,title,note)=>`<div class="chapter-head"><div class="chapter-kicker"><span>${n}</span><span class="chapter-rule"></span></div><div class="chapter-heading"><h2>${title}</h2>${note?`<p>${note}</p>`:''}</div></div>`;
const safeLink=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;

function header(){return `<header class="topbar"><div class="topbar-inner"><a href="#main" class="brand" aria-label="GRIDIRON LAB"><span class="brand-mark"><i></i><i></i><i></i></span><span>GRIDIRON<span class="brand-slash">/</span>LAB</span></a><nav class="navigation" aria-label="Primary">${Object.entries(tabNames).map(([id,text])=>`<button type="button" class="nav-item ${state.tab===id?'active':''}" data-action="tab-${id}" aria-current="${state.tab===id?'page':'false'}">${esc(text)}</button>`).join('')}</nav><div class="topbar-meta"><span class="signal"></span> 2026 SEASON</div></div></header>`;}
function topper(section,title,description){return `<section class="page-intro"><div class="page-intro-small"><span>GRIDIRON LAB / ${section}</span><span>EXPERIMENTAL FOOTBALL ENGINE / EDITION 09</span></div><div class="page-intro-body"><div><h1>${title}</h1><p>${description}</p></div><div class="intro-symbol" aria-hidden="true"><div class="football-laces"><i></i><i></i><i></i><i></i></div></div></div></section>`;}
function callout(message,cls=''){return `<div class="editor-note ${cls}" role="note"><span class="note-icon" aria-hidden="true">i</span><p>${message}</p></div>`;}
function errorBox(){return state.error?`<div class="error-strip" role="alert">${esc(state.error)}</div>`:'';}
function matchupPicker(){const c=state.config;return `<section class="play-console" aria-labelledby="match-heading"><div class="console-intro"><div><span class="eyebrow">01 / SET THE MATCHUP</span><h2 id="match-heading">Who plays whom?</h2></div><span class="console-season">138 FBS programs · 2026</span></div><div class="console-controls"><label class="team-control"><small>TEAM ONE</small>${ctl('a',fbs.map(t=>[t.id,t.name]),c.a)}</label><span class="versus">vs</span><label class="team-control"><small>TEAM TWO</small>${ctl('b',fbs.map(t=>[t.id,t.name]),c.b)}</label><label class="venue-control"><small>LOCATION</small>${ctl('venue',[['neutral','Neutral field'],['a',name(c.a)+' at home'],['b',name(c.b)+' at home']],c.venue)}</label></div><div class="console-footer"><span>Pick the teams and venue. Everything else is automatic.</span>${button('new-game','Simulate a new game <span aria-hidden="true">↗</span>','primary')}</div></section>`;}
function matchupForecast(){const e=evaluatedMatchup(state.config.a,state.config.b,state.config.venue),m=state.forecast,c=state.config;
 if(!e)return `<section class="research-snapshot unavailable"><div class="snapshot-head"><span class="eyebrow">PREGAME RESEARCH ESTIMATE</span>${tag('Empirical file unavailable','warning')}</div><h3>No independently fitted projection loaded.</h3><p>The game below remains playable in synthetic mode. Source-derived winner probabilities are intentionally withheld until the validated research data are available.</p><p>${safeLink('https://github.com/jviola1019/hypothetical_cfb/blob/main/docs/MODEL_CARD.md','See methodology')}</p></section>`;
 const sa=e.expectedA,sb=e.expectedB,margin=sa-sb,line=(margin>0?'-':margin<0?'+':'')+fmt(Math.abs(margin));
 return `<section class="research-snapshot" aria-label="Historical-form model"><div class="snapshot-head"><span class="eyebrow">PREGAME RESEARCH ESTIMATE</span>${tag('Observed-results model','empirical')}</div><div class="snapshot-grid"><div class="snapshot-lead"><small>${esc(short(c.a))} WIN PROBABILITY</small><strong>${percent(e.pA)}</strong><p>Opponent rating comparison from the frozen Elo research file.</p><div class="probability-track" role="img" aria-label="${esc(name(c.a))} ${percent(e.pA)}, ${esc(name(c.b))} ${percent(e.pB)}"><span style="width:${(e.pA*100).toFixed(2)}%"></span></div><div class="probability-end"><b>${esc(short(c.a))} ${percent(e.pA)}</b><b>${esc(short(c.b))} ${percent(e.pB)}</b></div></div><div class="snapshot-figures"><div><small>POINT ESTIMATE</small><strong>${fmt(sa)} <em>–</em> ${fmt(sb)}</strong></div><div><small>MODEL SPREAD · ${esc(short(c.a))}</small><strong>${line}</strong></div><div><small>MODEL TOTAL</small><strong>${fmt(sa+sb)}</strong></div><div><small>RATING DIFFERENCE</small><strong>${fmt(e.ratingA-e.ratingB,0)}</strong></div></div></div><div class="snapshot-foot">2026 data through ${esc(String(e.lastScoredGame||e.asOf).slice(0,10))} · Winner estimate and score-center estimate use different research formulas. The displayed spread is the negative of the expected A−B point margin. Neither is a market line. ${safeLink('./docs/MODEL_CARD.md','How it works')}</div></section>`;}
function scoreboard(g,mode='game'){if(!g)return `<div class="scoreboard-empty">Building a new game…</div>`;
 const a=g.config.a,b=g.config.b;return `<section class="fixture-score" aria-label="Simulated game result"><div class="fixture-meta"><span><span class="live-indicator"></span> FINAL / ${mode==='game'?'GENERATED GAME':'PLAYOFF GAME'}</span>${tag('Hypothetical • uncalibrated')}</div><div class="fixture-center"><div class="fixture-team"><span class="team-abbr">${esc(short(a))}</span><strong>${esc(name(a))}</strong><small>${esc(g.config.venue==='a'?'HOME':g.config.venue==='b'?'AWAY':'NEUTRAL')}</small></div><div class="fixture-score-number"><b>${integer(g.final[0])}</b><span>:</span><b>${integer(g.final[1])}</b></div><div class="fixture-team away"><span class="team-abbr">${esc(short(b))}</span><strong>${esc(name(b))}</strong><small>${esc(g.config.venue==='b'?'HOME':g.config.venue==='a'?'AWAY':'NEUTRAL')}</small></div></div><div class="fixture-summary"><span>${esc(name(g.winner))} won the generated game</span><span>${esc(locationName(g.config))} · ${g.ot?g.ot+' OT':'Regulation'} · Seed ${esc(g.seed)}</span></div><div class="field-ruler" aria-hidden="true"><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span><span>40</span><span>30</span><span>20</span><span>10</span></div></section>`;}
function quarterTable(g){if(!g)return '';const quarters=i=>g.teams[i].byQuarter.map(n=>`<td>${integer(n)}</td>`).join('');const ot=i=>g.teams[i].overtimePoints;return `<div class="table-scroll"><table class="score-table"><caption>Scoring by quarter — hypothetical</caption><thead><tr><th>TEAM</th><th>Q1</th><th>Q2</th><th>Q3</th><th>Q4</th>${g.ot?'<th>OT</th>':''}<th>FINAL</th></tr></thead><tbody>${g.teams.map((t,i)=>`<tr><th>${esc(short(t.team))}</th>${quarters(i)}${g.ot?`<td>${integer(ot(i))}</td>`:''}<td><strong>${integer(g.final[i])}</strong></td></tr>`).join('')}</tbody></table></div>`;}
const stats=[['plays','Offensive plays'],['passAttempts','Pass attempts'],['completions','Completions'],['passYards','Passing yards'],['rushAttempts','Rush attempts'],['rushYards','Rushing yards'],['passingTD','Pass TD'],['rushingTD','Rush TD'],['turnovers','Turnovers'],['drives','Drives']];
function statsTable(g){return `<div class="table-scroll"><table class="stat-table"><caption>Generated team box score</caption><thead><tr><th>STATISTIC</th><th>${esc(short(g.config.a))}</th><th>${esc(short(g.config.b))}</th></tr></thead><tbody>${stats.map(([key,label])=>`<tr><th>${label}</th><td>${integer(g.teams[0][key])}</td><td>${integer(g.teams[1][key])}</td></tr>`).join('')}</tbody></table></div>`;}
function playerBoxes(g){const roles=['QB','RB','WR1','WR2','TE','K'];const rows=g.teams.flatMap(team=>roles.map(role=>({team:team.team,role,data:team.players[role]})).filter(x=>x.data?.historical));
 if(!rows.length)return `<div class="empty-panel">Roster-linked full names are not available for this matchup. The engine did not invent player identities.</div>`;
 const line=x=>{const p=x.data,r=x.role;if(r==='QB')return `${integer(p.passingYards)} passing yds · ${p.completions}/${p.passingAttempts} · ${p.passingTD} pass TD`;if(r==='RB')return `${integer(p.rushYards)} rushing yds · ${p.rushAttempts} carries · ${p.receptions} rec`;if(r==='K')return `${p.fieldGoalsMade}/${p.fieldGoalsAttempted} FG · ${p.extraPointsMade} XP`;return `${p.receptions} catches · ${integer(p.receivingYards)} yds`};
 return `<div class="table-scroll"><table class="stat-table athletes"><caption>Generated roster-linked player statistics</caption><thead><tr><th>PLAYER / TEAM</th><th>ROLE SLOT</th><th>SIMULATED LINE</th></tr></thead><tbody>${rows.map(x=>`<tr><th>${esc(x.data.label)}<small>${esc(name(x.team))} · ${x.data.rosterSeason===2026?'2026 roster':'unassigned'} · ${x.data.eventGames?'observed event ranking':'role allocation is fictional'}</small></th><td>${esc(x.role.replace(/[12]/,''))}</td><td>${esc(line(x))}</td></tr>`).join('')}</tbody></table></div><p class="subcaption">Roster-listed names do not verify starters, availability or actual player involvement. Role allocation is fictional.</p>`;}
function positionField(g){
 // Coordinates are simulated starting positions, not observed EPA or a play chart.
 const marks=g.drives.map((d,i)=>{const y=36+(i%3)*17;const x=30+Math.max(0,Math.min(100,d.start))*5.6;const color=d.points?'#d5ef67':d.outcome==='TO'?'#f1ae71':'#8ba58d';return `<circle cx="${x}" cy="${y}" r="${d.points?5.2:3.8}" fill="${color}"><title>Drive ${i+1}: ${short(d.offense)} starts at ${d.start}, ${d.outcome} (${d.points} points)</title></circle>`;}).join('');
 return `<svg class="viz field-diagram" viewBox="0 0 625 130" role="img" aria-label="Generated starting field positions for ${g.drives.length} possessions"><title>Starting field positions from the simulated drive log</title><rect x="30" y="24" width="560" height="80" fill="#182a1d" stroke="#65795c"/>${Array.from({length:11},(_,i)=>`<line x1="${30+i*56}" x2="${30+i*56}" y1="24" y2="104" stroke="#547052" stroke-width="${i===5?1.8:1}" opacity=".65"/>`).join('')}<line x1="30" x2="590" y1="64" y2="64" stroke="#455f45" stroke-dasharray="6 8"/>${marks}<text x="30" y="118" fill="#9cac94" font-size="10" font-family="monospace">OWN END ZONE</text><text x="590" y="118" text-anchor="end" fill="#9cac94" font-size="10" font-family="monospace">OPPONENT END ZONE</text></svg>`;
}
function driveLog(g){return `<div class="table-scroll"><table class="stat-table drive-table"><caption>Generated possession summary</caption><thead><tr><th>#</th><th>OFFENSE</th><th>PERIOD</th><th>START YD</th><th>PLAYS</th><th>RESULT</th><th>POINTS</th></tr></thead><tbody>${g.drives.map((d,i)=>`<tr><td>${i+1}</td><td>${esc(short(d.offense))}</td><td>${esc(d.quarter)}</td><td>${d.start}</td><td>${d.plays}</td><td>${esc(d.outcome)}</td><td>${d.points}</td></tr>`).join('')}</tbody></table></div>`;}
function gameDetail(g,sectionID='game-details'){if(!g)return '';return `<section class="game-inside" id="${sectionID}">${subtitle('03','The game tape','Every drive and every player statistic comes from the same simulated game.')}<div class="two-viz"><article class="viz-sheet"><div class="viz-head"><span>PLAYBACK 01</span><h3>Score progression</h3></div>${scoreboardCurve(g)}<div class="viz-legend"><span><i class="dot warm"></i>${esc(short(g.config.a))}</span><span><i class="dot cool"></i>${esc(short(g.config.b))}</span></div></article><article class="viz-sheet"><div class="viz-head"><span>PLAYBACK 02</span><h3>Possession map</h3></div>${driveStrip(g)}<p class="micro">Bars represent generated drive gains and outcomes, not true play-by-play data.</p></article></div><div class="position-sheet"><div class="viz-head"><span>PLAYBACK 03 / FIELD GEOMETRY</span><h3>Where possessions began</h3><p>Color highlights generated scoring drives and turnovers; no observed field tracking is implied.</p></div>${positionField(g)}</div><div class="ledger-grid"><article class="sheet"><h3>Team box score</h3>${statsTable(g)}</article><article class="sheet"><h3>Named players</h3>${playerBoxes(g)}</article></div><details class="disclosure"><summary>Read every generated possession <span>${g.drives.length} entries</span></summary>${driveLog(g)}</details></section>`;}
function syntheticDistribution(){const m=state.forecast;if(!m)return `<div class="loading-panel" aria-live="polite">${state.running?`Analyzing ${state.progress}%...`:'Preparing score distributions...'}</div>`;
 return `<section class="sample-outlook">${subtitle('02','What happens across replays','The shaded outcomes below come from thousands of fictional games, not a verified market or forecast.')}<div class="sampling-line"><span>${tag('Generated games only')}</span><span>${integer(m.n)} replays · Monte Carlo error ${percent(m.mcse)}</span></div><div class="outcome-strip"><div><small>${esc(short(state.config.a))} WON</small><b>${percent(m.pA)}</b><span>Share of simulated games</span></div><div><small>AVERAGE GENERATED SCORE</small><b>${integer(m.meanA)} : ${integer(m.meanB)}</b><span>Not the same as research projection</span></div><div><small>GENERATED TOTAL</small><b>${fmt(m.totalMean)}</b><span>90% range ${m.totalInterval.join('–')}</span></div><div><small>OT RATE</small><b>${percent(m.ot)}</b><span>In the simulator only</span></div></div><div class="two-viz"><article class="viz-sheet"><div class="viz-head"><span>OUTCOME STUDY A</span><h3>Winning margins</h3><p>Points for Team A minus points for Team B.</p></div>${histogram(m.margin,0,'margin')}</article><article class="viz-sheet"><div class="viz-head"><span>OUTCOME STUDY B</span><h3>Total scoring</h3><p>Combined points in the generated games.</p></div>${histogram(m.total,m.totalMean,'total')}</article></div><details class="disclosure outcome-explorer"><summary>Explore the full score map <span>7-point score cells</span></summary><div class="expanded-chart"><div class="viz-head"><span>JOINT-SCORE FREQUENCY</span><h3>Two-team outcome atlas</h3><p>Each cell shows the share of fictional results in a score range.</p></div>${atlas(m.scores,m.n)}</div></details></section>`;}
function propTable(){const m=state.forecast,props=m?.props||[],observedRows=[...observedPropRows(state.config.a),...observedPropRows(state.config.b)];
 const synthetic=props.length?`<div class="table-scroll"><table class="stat-table prop-table"><caption>Illustrative generated prop outcomes</caption><thead><tr><th>ROSTER-LINKED ATHLETE</th><th>STAT</th><th>ILLUSTRATIVE LINE</th><th>GENERATED AVG.</th><th>OVER SHARE</th><th></th></tr></thead><tbody>${props.map(p=>`<tr><th>${esc(p.fullName)}<small>${esc(name(p.team))} · 2026 roster · illustrative ${esc(p.role)} slot</small></th><td>${esc(p.unit)}</td><td>${fmt(p.line)}</td><td>${fmt(p.mean)}</td><td><strong>${percent(p.above)}</strong></td><td>${button('prop:'+p.id,'View chart','subtle')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-panel">There are no roster-linked synthetic props for the selected teams yet. No player names or probabilities are fabricated.</div>`;
 const picked=props.find(x=>x.id===state.selectedProp),detail=picked?`<div class="expanded-chart"><div class="viz-head"><span>ILLUSTRATIVE PROP DISTRIBUTION / ${esc(picked.fullName)}</span><h3>${esc(picked.unit)} above ${fmt(picked.line)}</h3></div>${propBars(picked.values,picked.line)}<p>Share above line: ${percent(picked.above)} across ${picked.n} fictional games. Not an independently validated player forecast.</p></div>`:'';
 const recorded=observedRows.length?`<details class="disclosure"><summary>See observed 2026 player form <span>${observedRows.length} examples</span></summary><div class="table-scroll"><table class="stat-table"><thead><tr><th>PLAYER</th><th>OBSERVED STAT</th><th>RECORDED GAMES</th><th>AVG.</th><th>HIT RATE IN RECORDED GAMES</th></tr></thead><tbody>${observedRows.slice(0,24).map(p=>`<tr><th>${esc(p.name)}<small>${esc(name(p.team))}</small></th><td>${esc(p.label)}</td><td>${p.n}</td><td>${fmt(p.mean)}</td><td>${percent(p.hitRate)}</td></tr>`).join('')}</tbody></table></div><p class="subcaption">Only games where the statistic was recorded enter this table. Missing games and nonparticipation are not modeled as zeros.</p></details>`:`<p class="micro">Observed player-event summaries have not been loaded for these teams.</p>`;
 return `<section class="player-desk">${subtitle('04','The player sheet','Full roster-listed names when available; generated stat lines and observed player form are separated.')}<div class="prop-label">${tag('Synthetic scenarios')}<span>No sportsbook odds or verified starting lineups</span></div>${synthetic}${detail}${recorded}</section>`;}
function historyTable(){const c=state.config,a=observed(c.a,2026),b=observed(c.b,2026),a25=observed(c.a,2025),b25=observed(c.b,2025);
 const row=(title,x,y,kind='')=>`<tr><th>${title}</th><td>${x==null?'—':kind==='number'?fmt(x):esc(x)}</td><td>${y==null?'—':kind==='number'?fmt(y):esc(y)}</td></tr>`;
 return `<details class="disclosure team-history"><summary>Compare historical team results <span>2026 / 2025</span></summary><div class="table-scroll"><table class="stat-table"><thead><tr><th>HISTORICAL RESULT</th><th>${esc(name(c.a))}</th><th>${esc(name(c.b))}</th></tr></thead><tbody><tr class="band"><th colspan="3">2026 · OBSERVED SEASON-TO-DATE</th></tr>${row('W–L',a?.record,b?.record)}${row('Points per game',a?.pointsFor,b?.pointsFor,'number')}${row('Points allowed',a?.pointsAgainst,b?.pointsAgainst,'number')}<tr class="band"><th colspan="3">2025 · COMPLETED SEASON</th></tr>${row('W–L',a25?.record,b25?.record)}${row('Points per game',a25?.pointsFor,b25?.pointsFor,'number')}${row('Points allowed',a25?.pointsAgainst,b25?.pointsAgainst,'number')}</tbody></table></div><p class="subcaption">These are actual observations from published snapshots, not game-generator outputs.</p></details>`;}
function rosterCoverageCard(g){
  const ids=[state.config.a,state.config.b], names=ids.map(id=>rosterForTeam(id,2026).length);
  const active=sourceStatus.rosters[2026];
  const colored=names.every(n=>n>0)?'roster-good':'roster-missing';
  return `<div class="roster-coverage ${colored}" aria-live="polite"><span class="roster-coverage-mark">26</span><div><b>2026 roster edition</b><p>${ids.map((id,i)=>`${esc(name(id))}: ${names[i]} listed athletes`).join(' · ')} · Data issued ${esc(active?.asOf||'not downloaded')}</p><small>Full names are season-specific; simulated QB, RB, receiver and kicker roles are illustrative, never confirmed starters.</small></div></div>`;
}
function gamePage(){const g=state.game;return `${topper('GAME SIMULATION','THE MATCHUP.<br><em>YOUR CALL.</em>','Two schools. One field. A new game every time. The math stays visible, not in your way.')}${matchupPicker()}${rosterCoverageCard(g)}${errorBox()}<div class="game-canvas"><div class="lead-section"><span class="eyebrow">02 / THE GENERATED RESULT</span><div class="lead-actions"><span class="narrative-dot"></span><span>ONE POSSIBLE OUTCOME</span></div></div>${scoreboard(g)}${g?quarterTable(g):''}<div class="result-buttons">${button('new-game','Play it again <span aria-hidden="true">↗</span>','primary')}<a class="jump-link" href="#game-details">Jump to box score ↓</a></div></div>${matchupForecast()}${syntheticDistribution()}${gameDetail(g)}${propTable()}${historyTable()}`;}
function tournamentOverview(){const t=state.tournament,rs=t.rounds,played=rs.reduce((s,r)=>s+r.matches.filter(m=>m.game).length,0),f=FORMAT_MAP[t.formatId];return `<div class="tournament-overview"><div><small>FIELD</small><b>${f.size} teams</b></div><div><small>COMPLETED</small><b>${played} / ${f.size-1}</b></div><div><small>CHAMPION</small><b>${t.champion?esc(name(t.champion)):'Not determined'}</b></div></div>`;}
/** No more than 16 rendered games per large-field page; accessible round selector. */
function bracketRounds(){
 const t=state.tournament,f=FORMAT_MAP[t.formatId];
 const rs=t.rounds.map((r,i)=>({name:r.name,stage:i,matches:r.matches}));
 if(!t.champion)rs.push({name:roundNameForView(t.formatId,t.stage),stage:t.stage,
   matches:Array.from({length:t.slots.length/2},(_,i)=>({a:t.slots[2*i],b:t.slots[2*i+1],game:t.played[i]||null,bye:!t.slots[2*i]||!t.slots[2*i+1]}))});
 const one=m=>{const game=m.game,winner=game?.winner||m.winner;
   return `<button type="button" class="fixture-bracket ${game?'is-final':''}" ${game?'':'disabled'} data-action="inspect:${m.stage}:${m.index}" aria-label="${game?'Inspect':'Pending'} ${esc(name(m.a))} versus ${esc(name(m.b))}"><span class="bracket-status">${game?'FINAL':m.bye?'ADVANCES / BYE':'TO BE PLAYED'}</span><span class="bracket-team ${winner===m.a&&game?'win':''}"><b>${m.a?esc(short(m.a)):'OPEN'}</b><span>${m.a?esc(name(m.a)):'OPEN'}</span><strong>${game?game.final[0]:'—'}</strong></span><span class="bracket-team ${winner===m.b&&game?'win':''}"><b>${m.b?esc(short(m.b)):'BYE'}</b><span>${m.b?esc(name(m.b)):'BYE'}</span><strong>${game?game.final[1]:'—'}</strong></span></button>`;};
 if(f.size<=24)return `<div class="bracket-shell"><div class="bracket-scroll" tabindex="0" role="region" aria-label="Horizontal playoff bracket">${rs.map((r,j)=>`<section class="bracket-column"><div class="bracket-col-head"><span>ROUND ${j+1}</span><h3>${esc(r.name)}</h3></div>${r.matches.map((m,i)=>one({...m,stage:r.stage,index:i})).join('')}</section>`).join('')}</div></div>`;
 const roundIndex=Math.max(0,Math.min(rs.length-1,state.bracketViewRound));
 const selected=rs[roundIndex];const n=selected.matches.length;
 const indexed=selected.matches.map((m,i)=>({...m,index:i,stage:selected.stage}));
 // Preliminary round: most spots are automatic advances. Hide empty pairing cards.
 const all=indexed.filter(x=>x.a&&x.b);
 const groups=['all','1','2','3','4'];
 const regionFiltered=state.bracketQuadrant==='all'?all:all.filter(m=>Math.floor(m.index/Math.ceil(n/4))===Number(state.bracketQuadrant)-1);
 const perPage=16,maxPage=Math.max(0,Math.ceil(regionFiltered.length/perPage)-1),pg=Math.min(state.bracketViewPage,maxPage);
 const visible=regionFiltered.slice(pg*perPage,(pg+1)*perPage);
 return `<section class="bracket-atlas" aria-label="Large-field tournament explorer"><div class="atlas-topline"><div><span class="eyebrow">ROUND ATLAS / ${f.size} TEAMS</span><h3>${esc(selected.name)}</h3></div><p>${all.length} matchups · ${selected.matches.filter(m=>m.bye).length} automatic advances · ${pg+1}/${maxPage+1} pages</p></div>
 <div class="round-switches" role="group" aria-label="Tournament round">${rs.map((r,i)=>button('round:'+i,esc(r.name),i===roundIndex?'selected':'subtle')).join('')}</div>
 <div class="atlas-filters"><label for="bracket-quadrant">Bracket quadrant</label>${ctl('bracket-quadrant',groups.map(x=>[x,x==='all'?'All four':`Quadrant ${x}`]),state.bracketQuadrant)}<span>Quadrants show bracket lanes, not geographic regions.</span></div>
 <div class="bracket-grid">${visible.length?visible.map(m=>one(m)).join(''):'<p class="empty-panel">No played matchups in this bracket lane yet.</p>'}</div>
 <div class="atlas-pager"><button class="action outline" type="button" data-action="page:${Math.max(0,pg-1)}" ${pg===0?'disabled':''}>Previous</button><span>Games ${regionFiltered.length?pg*perPage+1:0}–${Math.min((pg+1)*perPage,regionFiltered.length)} of ${regionFiltered.length}</span><button class="action outline" type="button" data-action="page:${Math.min(maxPage,pg+1)}" ${pg===maxPage?'disabled':''}>Next</button></div></section>`;
}
function roundNameForView(id,stage){const f=FORMAT_MAP[id];const rounds=Math.ceil(Math.log2(f.size)),remaining=rounds-stage;
 if(remaining===1)return 'Championship';if(remaining===2)return 'Semifinals';if(remaining===3)return 'Quarterfinals';
 if(f.size===138&&stage===0)return 'FBS Play-in · 138 to 128';
 if(f.size===68&&stage===0)return 'First Four · 68 to 64';
 const width=2**remaining;
 if(stage===0&&f.size!==width)return 'Qualifying round';
 return width===128?'Round of 128':width===64?'Round of 64':width===32?'Round of 32':width===16?'Round of 16':'First round';
}
function titleLeaderboard(){const r=state.tournamentMC;if(!r)return `<div class="empty-panel"><strong>Want to see the most common champion?</strong><p>Run the title study to replay the entire bracket 400 times.</p></div>`;const ranking=Object.entries(r.probabilities).sort((a,b)=>b[1]-a[1]);return `<div class="table-scroll"><table class="stat-table odds-table"><thead><tr><th>SCHOOL</th><th>CHAMPIONSHIP SHARE</th><th>SIMULATION ERROR</th></tr></thead><tbody>${ranking.map(([id,p],i)=>`<tr><th><span class="ranking-num">${String(i+1).padStart(2,'0')}</span>${esc(name(id))}</th><td><div class="odds-bar"><span style="width:${(100*p).toFixed(2)}%"></span></div><b>${percent(p)}</b></td><td>±${percent(Math.sqrt(p*(1-p)/r.n))}</td></tr>`).join('')}</tbody></table></div><p class="subcaption">Entire brackets were simulated together. These are fictional championship frequencies, not empirically calibrated odds.</p>`;}
function playoffGameInspector(){const item=state.selectedMatch;if(!item)return '';const g=item.game;return `<section class="inspector-view" id="game-inspector">${subtitle('03','Inside the playoff game',`${esc(item.round)} · Every number below is generated from one game.`)}${button('close-inspector','Close report','subtle')}${scoreboard(g,'playoff')}${quarterTable(g)}${gameDetail(g,'inspected-game-details')}<section class="player-desk">${subtitle('04','Player notes','Generated roster-linked statistics and historical evidence are not the same thing.')} ${playerBoxes(g)}</section></section>`;}
function seedEditor(){
 const t=state.tournament,f=FORMAT_MAP[t.formatId],source=ranked2026Field();
 const locked=!!(t.champion||t.stage||t.rounds.length||Object.keys(t.played).length),disabled=locked||!state.sourcesReady;
 const choices=t.participants.map((id,i)=>[String(i),`#${i+1} · ${name(id)}`]);
 const ranked=f.size>=68?'National bracket':'Field bracket';
 const defaultList=t.participants.slice(0,Math.min(16,f.size));
 return `<div class="bracket-seeding"><div class="seed-intro"><div><span class="eyebrow">2026 PROVISIONAL FIELD ORDER</span><h3>${ranked} / ${f.size} entrants</h3><p>${esc(t.seedingSource||source.source)} · Data ${esc(source.asOf||'unavailable')}. NOT official CFP ranking or seeding.</p></div><span class="seed-source-chip">${source.covered||0} rated schools</span></div>
 <div class="seed-leaders" aria-label="Highest seeds">${defaultList.map((id,i)=>`<div class="seed-row"><strong>${String(i+1).padStart(2,'0')}</strong><span>${esc(name(id))}</span><small>${source.scores?.[id]?fmt(source.scores[id],0)+' ELO':'2026 FBS'}</small></div>`).join('')}</div>
 <details class="seed-expander"><summary>Open full ${f.size}-team seed list</summary><div class="seed-all-scroll" role="region" tabindex="0" aria-label="Complete ordered field"><table class="stat-table"><caption>Provisional seed list · seeded from current model, not committee rankings</caption><thead><tr><th>SEED</th><th>SCHOOL</th><th>RATING / EVIDENCE</th></tr></thead><tbody>${t.participants.map((id,i)=>`<tr><td>#${i+1}</td><th>${esc(name(id))}</th><td>${source.scores?.[id]?fmt(source.scores[id],0)+' ELO':'Unranked / fallback'}</td></tr>`).join('')}</tbody></table></div></details><div class="restore-wrap">${button('restore-ranked','Restore model-ranked field','subtle')}</div>
 <div class="swap-desk"><div class="swap-label"><b>Make a seed trade</b><span>${locked?'Bracket already started. Reset to edit.':'Swap any two seeds before the first game. No team is added or dropped.'}</span></div><div class="swap-controls"><label>From seed ${ctl('swap-from',choices,String(state.seedFrom))}</label><label>With seed ${ctl('swap-to',choices,String(state.seedTo))}</label>${disabled?'<button class="action primary" type="button" disabled>Reset to edit</button>':button('swap-seeds','Swap positions ↔','primary')}</div></div></div>`;
}
function playoffPage(){const f=FORMAT_MAP[state.format],n=f.size,pregame=!state.tournament.rounds.length;
 const explanation=f.kind==='official-fbs'?'Official CFP bracket geometry; entries and model seed order are hypothetical—not the actual committee field.':f.kind==='hypothetical'?'An alternative national championship: fantasy structure, FBS rosters, and model seed order.':'FCS-inspired geometry with mixed teams; NOT an official FCS field.';
 return `${topper('PLAYOFF SIMULATION',n>=68?'EVERY TEAM.<br><em>ONE TITLE.</em>':'THE ROAD<br><em>TO THE TITLE.</em>',n>=68?(ranked2026Field().covered?'A true national open. Start with the strongest model-rated 2026 teams, trade seeds, then write a new history.':'A national open. Team rankings are currently unavailable, so the field is unranked until research data load.'):(ranked2026Field().covered?'Provisional 2026 model seeds. Swap the seeds. Every game has its own report.':'Unranked fallback: no rating artifact available. The game remains playable.'))}
 <section class="playoff-console"><div class="console-intro"><div><span class="eyebrow">01 / CHOOSE YOUR TOURNAMENT</span><h2>Build the field.</h2></div><span class="console-season">${esc(f.season)}</span></div><div class="playoff-picker"><label><small>TOURNAMENT FORMAT</small>${ctl('format',FORMATS.filter(x=>x.kind!=='fcs-inspired').map(x=>[x.id,x.label]),state.format)}</label><div class="playoff-action-row">${state.sourcesReady?button('playoff-run',state.playoffBusy?'Simulating…':'Simulate tournament ↗','primary'):`<button type="button" class="action primary" disabled>Loading 2026 ratings…</button>`}${state.sourcesReady?button('playoff-mc',state.mcBusy?'Calculating…':'Estimate title share','outline'):'<button class="action outline" disabled>Title study</button>'}${button('playoff-reset','Reset bracket','subtle')}</div></div><p class="rules-note">${esc(explanation)}</p></section>${seedEditor()}${errorBox()}
 <section class="bracket-section">${subtitle('02','Your road to the final',n>=68?'Read one round at a time. Choose a quadrant to explore large fields. Select any played game for its complete report.':'Swipe across rounds and select any played game for its complete report.')}${tournamentOverview()}${bracketRounds()}</section>
 <section class="titles-section">${subtitle('03','Who takes the title?','Champion shares come from complete hypothetical tournament simulations, not sportsbook odds.')}
 <div class="champion-banner"><span>2026 FBS / NATIONAL CHAMPIONSHIP EXPERIMENT</span><h2>${state.tournament.champion?esc(name(state.tournament.champion)):'A champion awaits.'}</h2><p>${state.tournament.champion?'Winner of this one hypothetical bracket.':'Simulate the field to find a champion.'}</p></div>${titleLeaderboard()}</section>${playoffGameInspector()}`;
}
function actualData(){const rec=sourceStatus.seasons[2026],roster=sourceStatus.rosters[2026];return `<div class="data-grid"><article><span>2026 FBS PROGRAM INDEX</span><strong>${fbs.length}</strong><p>Included as selectable schools. Historical data coverage varies by artifact.</p></article><article><span>2026 VERIFIED RESULTS</span><strong>${rec?rec.schools:'—'}</strong><p>${rec?'Teams with installed season data':'Optional season snapshot not installed'}.</p></article><article><span>2026 ROSTER NAMES</span><strong>${roster?integer(roster.players):'—'}</strong><p>${roster?'Season-scoped identities, not active starters':'Optional roster snapshot not installed'}.</p></article></div>`;}
function seedingAudit(){const rank=ranked2026Field();
 if(!rank.covered)return `<p class="empty-panel">The 2026 rating artifact did not load, so no strength-ordered seed ranking is reported.</p>`;
 return `<details class="disclosure"><summary>2026 Elo seeding input <span>Top 20 · provisional</span></summary><div class="table-scroll"><table class="stat-table"><caption>2026 Elo research rating used for hypothetical bracket seeds</caption><thead><tr><th>RANK</th><th>TEAM</th><th>2026 ELO</th></tr></thead><tbody>${rank.ids.slice(0,20).map((id,i)=>`<tr><td>${i+1}</td><th>${esc(name(id))}</th><td>${fmt(rank.scores?.[id])}</td></tr>`).join('')}</tbody></table></div><p class="subcaption">As of ${esc(rank.asOf)}. Rating-based seeds are for fun tournament design, not the official College Football Playoff ranking. Actual simulated score outcomes use a separate, uncalibrated possession engine.</p></details>`;
}
function calibrationGraphic(){const doc=modelComparison();if(!doc)return `<div class="empty-panel">The independently evaluated benchmark artifact is not currently available. Results are not filled with fake numbers.</div>`;const labels={coin:'Coin flip',homeOnly:'Home-site baseline',elo:'Elo rating',margin:'Scoring-margin baseline',fixedBlend:'Fixed blend',logisticPair:'Two-feature logistic'},entry=doc.evaluation['2026'];return `<div class="table-scroll"><table class="stat-table model-table"><thead><tr><th>HISTORICAL MODEL</th><th>2025 VALIDATION BRIER</th><th>2026 FORWARD BRIER</th><th>2026 VISUAL COMPARISON</th></tr></thead><tbody>${Object.entries(labels).map(([id,label])=>`<tr ${doc.modelSelectedOn2025===id?'class="chosen-model"':''}><th>${label}${doc.modelSelectedOn2025===id?'<small>Picked using 2025 only</small>':''}</th><td>${fmt(doc.evaluation['2025'][id].brier,4)}</td><td>${fmt(entry[id].brier,4)}</td><td><div class="audit-meter" role="img" aria-label="Brier loss ${fmt(entry[id].brier,4)}"><span style="width:${(entry[id].brier/.35*100).toFixed(1)}%"></span></div></td></tr>`).join('')}</tbody></table></div><p class="subcaption">Lower Brier score is better. The 2026 set was inspected in previous iterations; do not treat it as untouched testing.</p>`;}
function reliabilityPlot(){const bins=modelComparison()?.reliability2026||[];if(!bins.length)return '<p>Calibration bins unavailable.</p>';const W=620,H=285,L=52,R=25,T=18,B=42,xx=p=>L+p*(W-L-R),yy=p=>T+(1-p)*(H-T-B);const pts=bins.map(v=>`<line x1="${xx(v.meanPrediction)}" x2="${xx(v.meanPrediction)}" y1="${yy(v.wilson95[1])}" y2="${yy(v.wilson95[0])}" stroke="#d6f065" stroke-width="2"/><circle cx="${xx(v.meanPrediction)}" cy="${yy(v.observedFrequency)}" r="5" fill="#d6f065"><title>${percent(v.meanPrediction)} predicted; ${percent(v.observedFrequency)} observed · n=${v.n}</title></circle>`).join('');return `<svg class="viz" viewBox="0 0 ${W} ${H}" role="img" aria-label="Model calibration plot with observed frequency against predicted probability"><title>Predicted win probability compared with actual win share</title>${[0,.25,.5,.75,1].map(v=>`<line x1="${L}" y1="${yy(v)}" x2="${W-R}" y2="${yy(v)}" stroke="#33403a"/><text x="${L-8}" y="${yy(v)+3}" text-anchor="end" fill="#adb9ae" font-size="12">${percent(v)}</text><text x="${xx(v)}" y="${H-17}" text-anchor="middle" fill="#adb9ae" font-size="12">${percent(v)}</text>`).join('')}<line x1="${L}" y1="${yy(0)}" x2="${xx(1)}" y2="${yy(1)}" stroke="#f4eee1" stroke-width="1.5" stroke-dasharray="6 7"/>${pts}<text x="${W/2}" y="${H-2}" text-anchor="middle" fill="#adb9ae" font-size="11">MEAN PREDICTED WIN CHANCE</text></svg>`;}
function scoreEvaluation(){const doc=scoreEvidence(),e=doc?.evaluations?.['2026'];if(!e)return `<div class="empty-panel">Score-distribution evaluation artifact unavailable.</div>`;return `<div class="coverage-bars"><div class="coverage-intro"><div><small>2026 EVALUATION</small><strong>${integer(e.n)}</strong><p>Completed historical FBS games evaluated.</p></div><div><small>MARGIN CRPS</small><strong>${fmt(e.margin.crps,2)}</strong><p>Lower is better; entire distribution matters.</p></div><div><small>TOTAL CRPS</small><strong>${fmt(e.total.crps,2)}</strong><p>Lower is better.</p></div></div>${[['Margin · 80%','margin',.8,'interval80Coverage'],['Margin · 90%','margin',.9,'interval90Coverage'],['Total · 80%','total',.8,'interval80Coverage'],['Total · 90%','total',.9,'interval90Coverage']].map(([label,type,target,k])=>`<div class="coverage-row"><span>${label}</span><div class="coverage-track"><i style="left:${(target*100).toFixed(1)}%"></i><b style="width:${(100*e[type][k]).toFixed(1)}%"></b></div><strong>${percent(e[type][k])}</strong></div>`).join('')}<p class="subcaption">Colored bar: observed interval coverage. Tick mark: target. These validate the historical residual distribution, not the possession simulator.</p></div>`;}
function playerEvaluation(){const x=playerModelEvaluation();if(!x)return `<div class="empty-panel">Conditional player-event model artifact not available.</div>`;return `<div class="evaluation-bar"><div><span>RECORDED PLAYER-STAT EVENTS</span><strong>${integer(x.model.n)}</strong></div><div><span>MODEL BRIER</span><strong>${fmt(x.model.brier,4)}</strong></div><div><span>COHORT PRIOR BRIER</span><strong>${fmt(x.cohortPriorOnlyBaseline.brier,4)}</strong></div></div><p class="subcaption">Population: recorded statistic-event games, not all scheduled games. This cannot establish unconditional player props without injury, availability and participation coverage.</p>`;}
function dataSources(){return `<details class="disclosure"><summary>Sources, model card & current limitations <span>read more</span></summary><div class="sources-grid"><div><h3>Observed game results</h3><p>2025/2026 SportsDataverse source snapshots and 2026 season-to-date metadata. Published results can lag.</p>${safeLink('https://github.com/sportsdataverse/cfbfastR-data','SportsDataverse')}</div><div><h3>Rosters and event summaries</h3><p>Names are historically roster-listed. Derived player events omit some non-appearances; no source claims an athlete is healthy or starting.</p>${safeLink('https://github.com/fakhar-ud-din/ncaapyscraper','School roster source')}</div><div><h3>Reproducibility and audit</h3><p>Seeded games, trained winner baseline, chronological evaluation and documented limitations.</p>${safeLink('./docs/VALIDATION_V08.md','Validation methodology')} · ${safeLink('./docs/MODEL_CARD.md','Model card')} · ${safeLink('./docs/STATUS.md','Status')}</div></div></details>`;}
function researchPage(){const status=researchStatus();return `${topper('MODEL & VALIDATION','SHOW YOUR<br><em>WORK.</em>','A separate research desk. This is where every number is challenged before it earns a place in the game.')}${callout('<strong>Read this first:</strong> Historical win predictions have empirical evaluation. The drive-by-drive engine and named-player game props remain synthetic. Monte Carlo error is not model accuracy.','important')}${subtitle('01','Evidence before precision','Real observations, fitted research and simulated outcomes are different layers.')}${actualData()}${seedingAudit()}<section class="audit-section">${subtitle('02','Which model held up?','Chronological baselines trained on older seasons; no postgame features in pregame research.')}${calibrationGraphic()}<div class="two-viz"><article class="viz-sheet"><div class="viz-head"><span>RELIABILITY STUDY</span><h3>Predicted versus observed</h3><p>Dashed diagonal = ideal calibration. Vertical lines = uncertainty.</p></div>${reliabilityPlot()}</article><article class="viz-sheet audit-explainer"><h3>How to read this chart</h3><p>If games assigned a 60% chance actually win only 45% of the time, the model is too confident in that group.</p><p><b>Brier score</b> penalizes inaccurate probability forecasts. Lower is better; 0.25 represents always predicting 50/50 in two-outcome games.</p><p><b>2026 is not pristine holdout data.</b> Earlier iterations already examined it.</p></article></div></section><section class="audit-section">${subtitle('03','How wide is the uncertainty?','Historical score-distribution validation, not drive or player calibration.')}${scoreEvaluation()}</section><section class="audit-section">${subtitle('04','What do player stats prove?','A recorded stat-event probability cannot be sold as a full-game player prop.')}${playerEvaluation()}</section><section class="audit-section">${subtitle('05','Methods, sources & caveats','The project remains inspectable and reproducible.')}${dataSources()}</section><div class="research-stamp">MODEL VERSION ${esc(status.version||'unavailable')} · LAST RECORDED GAME ${esc(String(status.lastScoredGame||'not installed').slice(0,10))} · ${esc(ENGINE_VERSION)}</div>`;}
